import { useMemo, useState } from "react";
import {
  ArrowUpRightIcon,
  ArrowsCounterClockwiseIcon,
  CheckCircleIcon,
  ClockIcon,
  FadersHorizontalIcon,
  FileArrowUpIcon,
  PauseIcon,
  PlayIcon,
  SealCheckIcon,
  SpinnerGapIcon,
  StatusWarningIcon,
  WarningIcon,
} from "./icons";
import { TransactionDetailsSheet } from "./transaction-details-sheet";
import { Button, buttonVariants } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  auditControls,
  batchStatusFilters,
  batchTransactions,
  buildBatchExportCsv,
  filterBatchTransactions,
  metrics,
  sourceLabels,
  type BatchStatus,
  type BatchStatusFilter,
  type BatchTransaction,
  type SourceKind,
} from "../../data";
import { cn } from "@/lib/utils";

const metricIcons = {
  clock: ClockIcon,
  seal: SealCheckIcon,
  warning: WarningIcon,
  arrows: ArrowsCounterClockwiseIcon,
} as const;

const sourceClassName: Record<SourceKind, string> = {
  oracle: "bg-(--source-oracle)/15 text-(--source-oracle)",
  sharepoint: "bg-(--source-sharepoint)/15 text-(--source-sharepoint)",
  concur: "bg-(--source-concur)/15 text-(--source-concur)",
  email: "bg-(--source-email)/15 text-(--source-email)",
};

const statusConfig: Record<
  BatchStatus,
  { label: string; className: string; Icon: typeof SpinnerGapIcon }
> = {
  processing: {
    label: "Processing",
    className: "text-(--status-processing)",
    Icon: SpinnerGapIcon,
  },
  completed: {
    label: "Completed",
    className: "text-(--status-completed)",
    Icon: CheckCircleIcon,
  },
  exception: {
    label: "Exception",
    className: "text-(--status-exception)",
    Icon: StatusWarningIcon,
  },
};

const tableHeadClassName =
  "h-12.5 bg-zinc-50 text-base tracking-tight dark:bg-card";

const outlineActionClassName = "h-8.5 gap-1 px-3.5 shadow-xs";

function LiveBadge({
  live,
  size = "md",
}: {
  live: boolean;
  size?: "md" | "sm";
}) {
  return (
    <span
      className={cn(
        "inline-flex items-center justify-center rounded-lg font-medium",
        live
          ? "bg-(--live)/10 text-(--live)"
          : "bg-muted text-muted-foreground",
        size === "md" && "gap-1.25 px-4 py-2.5 text-xs leading-4.5",
        size === "sm" &&
          "gap-[2.9px] rounded-[5.8px] px-[9.25px] py-[5.8px] text-[7px] leading-[10.4px]",
      )}
    >
      <span
        className={cn(
          "rounded-full",
          live ? "bg-(--live)" : "bg-muted-foreground",
          size === "md" ? "size-2.25" : "size-[5.2px]",
          live && size === "md" && "live-dot-pulse",
        )}
      />
      {live ? "Live" : "Paused"}
    </span>
  );
}

export function DashboardPage() {
  const [isLive, setIsLive] = useState<boolean>(auditControls.defaultLive);
  const [statusFilter, setStatusFilter] = useState<BatchStatusFilter>("all");
  const [selectedTransaction, setSelectedTransaction] =
    useState<BatchTransaction | null>(null);

  const filteredTransactions = useMemo(
    () => filterBatchTransactions(batchTransactions, statusFilter),
    [statusFilter],
  );

  const activeFilterLabel =
    batchStatusFilters.find((filter) => filter.value === statusFilter)?.label ??
    "All statuses";

  function handleRunAudit() {
    setIsLive(true);
  }

  function handlePause() {
    setIsLive(false);
  }

  function handleExport() {
    const csv = buildBatchExportCsv(filteredTransactions);
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `tallie-batch-${statusFilter}.csv`;
    link.click();
    URL.revokeObjectURL(url);
  }

  return (
    <div className="flex flex-col gap-10 px-4 py-6 md:px-8 md:py-10">
      <div className="flex flex-col gap-4 md:flex-row md:items-end md:justify-between">
        <div className="flex flex-col gap-1">
          <h1 className="font-serif text-3xl leading-snug tracking-tight">
            Three-Way Match Audit
          </h1>
          <p className="text-lg text-muted-foreground">
            Real time validation of transaction
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <LiveBadge live={isLive} />
          <Button
            className="h-10 gap-1 px-3.5"
            disabled={isLive}
            onClick={handleRunAudit}
          >
            Run Audit
            <PlayIcon />
          </Button>
          <Button
            variant="outline"
            className="h-10 gap-1 px-3.5 shadow-sm"
            disabled={!isLive}
            onClick={handlePause}
          >
            Pause
            <PauseIcon />
          </Button>
        </div>
      </div>

      <section className="flex flex-col gap-3">
        <h2 className="text-lg font-medium">Metrics</h2>
        <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
          {metrics.map((metric) => {
            const Icon = metricIcons[metric.icon];
            const showLiveTrend =
              "tone" in metric.trend && metric.trend.tone === "live";
            return (
              <div
                key={metric.id}
                className="flex h-37.5 flex-col justify-between rounded-xl border bg-zinc-50 p-4 dark:bg-card"
              >
                <div className="flex items-start gap-2">
                  <Icon className="size-5" />
                  <span className="text-sm font-medium tracking-tight">
                    {metric.label}
                  </span>
                </div>
                <div className="flex flex-col gap-3">
                  <p className="text-3xl leading-none font-medium">
                    {metric.value}
                  </p>
                  <div className="flex items-center gap-1 text-xs">
                    {"tone" in metric.trend && metric.trend.tone === "up" ? (
                      <ArrowUpRightIcon className="size-4 text-(--trend)" />
                    ) : null}
                    {showLiveTrend ? (
                      <SpinnerGapIcon
                        className={cn(
                          "size-4 text-(--status-processing)",
                          isLive && "animate-spin",
                        )}
                      />
                    ) : null}
                    <span>
                      <span className="font-medium">
                        {showLiveTrend
                          ? isLive
                            ? metric.trend.value
                            : "Paused"
                          : metric.trend.value}
                      </span>{" "}
                      <span className="text-muted-foreground">
                        {metric.trend.label}
                      </span>
                    </span>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </section>

      <section className="flex flex-col gap-5">
        <div className="flex flex-col gap-3 md:flex-row md:items-end md:justify-between">
          <div className="flex flex-col gap-2">
            <div className="flex flex-wrap items-center gap-2">
              <h2 className="text-lg font-medium">Current processing Batch</h2>
              <LiveBadge live={isLive} size="sm" />
            </div>
            <p className="text-sm text-muted-foreground">
              {isLive
                ? "Live transaction with auto scrolling"
                : "Audit paused — resume to continue processing"}
            </p>
          </div>
          <div className="flex w-full items-center justify-between md:w-auto md:justify-start md:gap-2">
            <DropdownMenu>
              <DropdownMenuTrigger
                type="button"
                className={buttonVariants({
                  variant: "outline",
                  className: outlineActionClassName,
                })}
              >
                {statusFilter === "all" ? "Filter" : activeFilterLabel}
                <FadersHorizontalIcon />
              </DropdownMenuTrigger>
              <DropdownMenuContent
                align="start"
                className="tallie-dashboard w-48"
              >
                <DropdownMenuRadioGroup
                  value={statusFilter}
                  onValueChange={(value) =>
                    setStatusFilter(value as BatchStatusFilter)
                  }
                >
                  {batchStatusFilters.map((filter) => {
                    const FilterIcon = filter.icon;
                    return (
                      <DropdownMenuRadioItem
                        key={filter.value}
                        value={filter.value}
                        className="gap-2 text-muted-foreground data-[state=checked]:font-medium data-[state=checked]:text-foreground"
                      >
                        <FilterIcon
                          className={cn(
                            filter.value === "processing" &&
                              "text-(--status-processing)!",
                            filter.value === "completed" &&
                              "text-(--status-completed)!",
                            filter.value === "exception" &&
                              "text-(--status-exception)!",
                          )}
                        />
                        {filter.label}
                      </DropdownMenuRadioItem>
                    );
                  })}
                </DropdownMenuRadioGroup>
              </DropdownMenuContent>
            </DropdownMenu>
            <Button
              variant="outline"
              className={outlineActionClassName}
              onClick={handleExport}
            >
              Export
              <FileArrowUpIcon />
            </Button>
          </div>
        </div>

        <div className="overflow-hidden rounded-xl bg-zinc-50/40 dark:bg-card/40">
          <Table>
            <TableHeader>
              <TableRow className="hover:bg-transparent">
                <TableHead className={cn(tableHeadClassName, "min-w-40 px-4")}>
                  Status
                </TableHead>
                <TableHead className={cn(tableHeadClassName, "min-w-45 px-0")}>
                  Transaction ID
                </TableHead>
                <TableHead
                  className={cn(tableHeadClassName, "min-w-42.5 px-0")}
                >
                  Vendor
                </TableHead>
                <TableHead
                  className={cn(tableHeadClassName, "min-w-42.5 px-0")}
                >
                  Amount
                </TableHead>
                <TableHead className={cn(tableHeadClassName, "min-w-60 px-0")}>
                  Sources
                </TableHead>
                <TableHead className={cn(tableHeadClassName, "min-w-35 px-0")}>
                  Confidence
                </TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {filteredTransactions.length === 0 ? (
                <TableRow className="hover:bg-transparent">
                  <TableCell
                    colSpan={6}
                    className="h-24 px-4 text-center text-muted-foreground"
                  >
                    No transactions match this filter.
                  </TableCell>
                </TableRow>
              ) : (
                filteredTransactions.map((row) => {
                  const status = statusConfig[row.status];
                  const StatusIcon = status.Icon;
                  return (
                    <TableRow
                      key={row.id}
                      className="h-18 cursor-pointer hover:bg-muted/50"
                      tabIndex={0}
                      onClick={() => setSelectedTransaction(row)}
                      onKeyDown={(event) => {
                        if (event.key === "Enter" || event.key === " ") {
                          event.preventDefault();
                          setSelectedTransaction(row);
                        }
                      }}
                    >
                      <TableCell className="px-4 py-4">
                        <div
                          className={cn(
                            "inline-flex h-7.5 items-center gap-2 rounded-xl py-1 pr-4 pl-3 text-sm font-medium",
                            status.className,
                          )}
                        >
                          <StatusIcon
                            className={cn(
                              "size-4",
                              row.status === "processing" &&
                                isLive &&
                                "animate-spin",
                            )}
                          />
                          {status.label}
                        </div>
                      </TableCell>
                      <TableCell className="px-0 py-4">
                        <div className="flex flex-col gap-1">
                          <span className="text-base font-medium tracking-tight">
                            {row.transactionId}
                          </span>
                          <span className="text-xs text-muted-foreground">
                            PO:: {row.po}
                          </span>
                        </div>
                      </TableCell>
                      <TableCell className="px-0 py-4 text-base font-medium tracking-tight">
                        {row.vendor}
                      </TableCell>
                      <TableCell className="px-0 py-4 font-mono text-base font-medium">
                        {row.amount}
                      </TableCell>
                      <TableCell className="px-0 py-4">
                        <div className="flex flex-wrap gap-1.5">
                          {row.sources.map((source) => (
                            <span
                              key={source}
                              className={cn(
                                "rounded px-2 py-0.5 text-xs tracking-tight",
                                source === "oracle" && "font-medium",
                                sourceClassName[source],
                              )}
                            >
                              {sourceLabels[source]}
                            </span>
                          ))}
                        </div>
                      </TableCell>
                      <TableCell className="px-0 py-4">
                        <div className="flex flex-col gap-1">
                          <span className="text-base font-medium tracking-tight">
                            {row.confidence}%
                          </span>
                          {"confidenceNote" in row && row.confidenceNote ? (
                            <span className="text-xs font-medium tracking-tight text-(--status-exception)">
                              {row.confidenceNote}
                            </span>
                          ) : null}
                        </div>
                      </TableCell>
                    </TableRow>
                  );
                })
              )}
            </TableBody>
          </Table>
        </div>
      </section>

      <TransactionDetailsSheet
        transaction={selectedTransaction}
        open={selectedTransaction !== null}
        onOpenChange={(open) => {
          if (!open) setSelectedTransaction(null);
        }}
      />
    </div>
  );
}

import {
  createContext,
  useContext,
  useMemo,
  useState,
  type AnchorHTMLAttributes,
  type MouseEvent,
  type ReactNode,
} from "react";

type DashboardNavigation = {
  pathname: string;
  navigate: (pathname: string) => void;
};

const DashboardNavigationContext = createContext<DashboardNavigation | null>(
  null,
);

export function DashboardNavigationProvider({
  children,
}: {
  children: ReactNode;
}) {
  const [pathname, setPathname] = useState("/");
  const value = useMemo(
    () => ({ pathname, navigate: setPathname }),
    [pathname],
  );

  return (
    <DashboardNavigationContext.Provider value={value}>
      {children}
    </DashboardNavigationContext.Provider>
  );
}

export function useDashboardNavigation() {
  const context = useContext(DashboardNavigationContext);

  if (!context) {
    throw new Error(
      "useDashboardNavigation must be used within DashboardNavigationProvider",
    );
  }

  return context;
}

export function DashboardLink({
  href,
  onClick,
  ...props
}: AnchorHTMLAttributes<HTMLAnchorElement> & { href: string }) {
  const { navigate } = useDashboardNavigation();

  function handleClick(event: MouseEvent<HTMLAnchorElement>) {
    onClick?.(event);

    if (
      event.defaultPrevented ||
      event.button !== 0 ||
      event.metaKey ||
      event.ctrlKey ||
      event.shiftKey ||
      event.altKey
    ) {
      return;
    }

    event.preventDefault();
    navigate(href);
  }

  return <a href={href} onClick={handleClick} {...props} />;
}

import {
  BookOpenIcon,
  CreditCardIcon,
  LogOutIcon,
  MessageCircleIcon,
  SettingsIcon,
  UserIcon as LucideUserIcon,
} from "lucide-react";
import {
  QuestionIcon,
  SidebarCollapseIcon,
  ToggleIcon,
  UserIcon,
} from "./icons";
import { TallieLogo } from "./logo";
import { DashboardLink, useDashboardNavigation } from "./navigation";
import { useTheme } from "./theme-provider";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuBadge,
  SidebarMenuButton,
  SidebarMenuItem,
  useSidebar,
} from "@/components/ui/sidebar";
import { currentUser, navigationGroups, type NavigationItem } from "../../data";
import { cn } from "@/lib/utils";

const menuButtonClassName = cn(
  "h-11 gap-2.5 rounded-lg px-3 text-base text-sidebar-foreground/70 transition-colors",
  "aria-[current=page]:bg-background aria-[current=page]:font-medium aria-[current=page]:text-sidebar-accent-foreground",
  "data-open:bg-background data-open:text-sidebar-accent-foreground",
  "[&_svg]:size-5!",
  "group-data-[collapsible=icon]:size-11! group-data-[collapsible=icon]:justify-center group-data-[collapsible=icon]:p-0! group-data-[collapsible=icon]:[&>span]:hidden",
);

const dropdownTriggerClassName =
  "peer/menu-button flex w-full items-center gap-2 overflow-hidden rounded-md p-2 text-left text-sm ring-sidebar-ring outline-hidden transition-[width,height,padding] hover:bg-sidebar-accent hover:text-sidebar-accent-foreground focus-visible:ring-2 active:bg-sidebar-accent active:text-sidebar-accent-foreground data-[state=open]:bg-sidebar-accent data-[state=open]:text-sidebar-accent-foreground [&>span:last-child]:truncate [&>svg]:size-4 [&>svg]:shrink-0";

function NavItem({ item }: { item: NavigationItem }) {
  const { pathname } = useDashboardNavigation();
  const { isMobile, setOpenMobile } = useSidebar();
  const isActive =
    item.href === "/"
      ? pathname === "/"
      : pathname === item.href || pathname.startsWith(`${item.href}/`);

  return (
    <SidebarMenuButton
      asChild
      tooltip={item.name}
      className={menuButtonClassName}
    >
      <DashboardLink
        href={item.href}
        aria-current={isActive ? "page" : undefined}
        onClick={() => {
          if (isMobile) setOpenMobile(false);
        }}
      >
        <item.icon />
        <span>{item.name}</span>
        {item.badge ? (
          <SidebarMenuBadge className="sidebar-badge-shadow static ml-auto rounded bg-background px-2 py-1.5 text-sm font-normal text-sidebar-foreground/70 group-aria-[current=page]/menu-button:font-medium group-aria-[current=page]/menu-button:text-sidebar-accent-foreground">
            {item.badge}
          </SidebarMenuBadge>
        ) : null}
      </DashboardLink>
    </SidebarMenuButton>
  );
}

function HelpItem() {
  return (
    <SidebarMenuItem>
      <DropdownMenu>
        <DropdownMenuTrigger
          type="button"
          className={cn(dropdownTriggerClassName, menuButtonClassName)}
          aria-label="Help"
        >
          <QuestionIcon />
          <span>Help</span>
        </DropdownMenuTrigger>
        <DropdownMenuContent
          side="top"
          align="start"
          className="tallie-dashboard w-56"
        >
          <DropdownMenuLabel className="font-normal">
            <p className="text-sm font-medium text-foreground">Need help?</p>
            <p>Guides, docs, and support for Tallie.</p>
          </DropdownMenuLabel>
          <DropdownMenuSeparator />
          <DropdownMenuGroup>
            <DropdownMenuItem asChild>
              <a
                href="https://docs.tallie.com"
                target="_blank"
                rel="noreferrer"
              >
                <BookOpenIcon />
                Documentation
              </a>
            </DropdownMenuItem>
            <DropdownMenuItem asChild>
              <a
                href="https://tallie.com/support"
                target="_blank"
                rel="noreferrer"
              >
                <MessageCircleIcon />
                Contact support
              </a>
            </DropdownMenuItem>
          </DropdownMenuGroup>
        </DropdownMenuContent>
      </DropdownMenu>
    </SidebarMenuItem>
  );
}

function DarkModeItem() {
  const { resolvedTheme, setTheme } = useTheme();
  const isDark = resolvedTheme === "dark";
  const label = isDark ? "Light Mode" : "Dark Mode";

  return (
    <SidebarMenuItem>
      <SidebarMenuButton
        tooltip={label}
        className={menuButtonClassName}
        onClick={() => setTheme(isDark ? "light" : "dark")}
      >
        <ToggleIcon pressed={isDark} />
        <span>{label}</span>
      </SidebarMenuButton>
    </SidebarMenuItem>
  );
}

function ProfileItem() {
  return (
    <SidebarMenuItem>
      <DropdownMenu>
        <DropdownMenuTrigger
          type="button"
          className={cn(dropdownTriggerClassName, menuButtonClassName)}
          aria-label="Profile"
        >
          <UserIcon />
          <span>Profile</span>
        </DropdownMenuTrigger>
        <DropdownMenuContent
          side="top"
          align="start"
          className="tallie-dashboard w-56"
        >
          <DropdownMenuLabel className="font-normal">
            <div className="leading-tight">
              <p className="text-sm font-medium text-foreground">
                {currentUser.name}
              </p>
              <p>{currentUser.email}</p>
            </div>
          </DropdownMenuLabel>
          <DropdownMenuSeparator />
          <DropdownMenuGroup>
            <DropdownMenuItem>
              <LucideUserIcon />
              Account
            </DropdownMenuItem>
            <DropdownMenuItem>
              <SettingsIcon />
              Preferences
            </DropdownMenuItem>
            <DropdownMenuItem>
              <CreditCardIcon />
              Billing
            </DropdownMenuItem>
          </DropdownMenuGroup>
          <DropdownMenuSeparator />
          <DropdownMenuItem variant="destructive">
            <LogOutIcon />
            Log out
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
    </SidebarMenuItem>
  );
}

function CollapseControl({
  collapsed,
  onToggle,
}: {
  collapsed: boolean;
  onToggle: () => void;
}) {
  if (!collapsed) {
    return (
      <button
        type="button"
        onClick={onToggle}
        className="flex size-9.5 shrink-0 items-center justify-center rounded-lg bg-secondary"
        aria-label="Collapse sidebar"
      >
        <SidebarCollapseIcon className="-rotate-90" />
      </button>
    );
  }

  return (
    <div className="relative size-11 shrink-0">
      <div className="pointer-events-none absolute inset-0 flex items-center justify-center transition-all ease-linear group-hover:scale-75 group-hover:opacity-0">
        <TallieLogo className="size-6" />
      </div>
      <div className="pointer-events-none absolute inset-0 flex scale-75 items-center justify-center opacity-0 transition-all ease-linear group-hover:pointer-events-auto group-hover:scale-100 group-hover:opacity-100">
        <button
          type="button"
          onClick={onToggle}
          className="flex size-11 items-center justify-center rounded-lg bg-secondary"
          aria-label="Expand sidebar"
        >
          <SidebarCollapseIcon className="rotate-90" />
        </button>
      </div>
    </div>
  );
}

export function DashboardSidebar() {
  const { state, toggleSidebar } = useSidebar();
  const collapsed = state === "collapsed";

  return (
    <Sidebar collapsible="icon" className="h-full border-none">
      <SidebarHeader
        className={cn(
          "h-16 flex-row items-center border-b border-sidebar-border transition-[padding] md:h-20",
          collapsed ? "justify-start px-3" : "justify-between gap-4.75 px-4",
        )}
      >
        {!collapsed && (
          <div className="flex min-w-0 flex-1 items-center gap-2">
            <TallieLogo className="size-8 shrink-0" />
            <span className="truncate text-xl font-semibold">Tallie</span>
          </div>
        )}
        <CollapseControl collapsed={collapsed} onToggle={toggleSidebar} />
      </SidebarHeader>

      <SidebarContent className="gap-4 overflow-x-hidden overflow-y-auto px-3 py-4 group-data-[collapsible=icon]:overflow-y-auto!">
        {navigationGroups.map((group) => (
          <SidebarGroup key={group.label} className="gap-2 p-0">
            <SidebarGroupLabel className="h-auto px-3 py-1 text-base font-normal text-muted-foreground">
              {group.label}
            </SidebarGroupLabel>
            <SidebarGroupContent>
              <SidebarMenu className="gap-2">
                {group.items.map((item) => (
                  <SidebarMenuItem key={item.name}>
                    <NavItem item={item} />
                  </SidebarMenuItem>
                ))}
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>
        ))}
      </SidebarContent>

      <SidebarFooter className="border-t border-sidebar-border px-3 py-3">
        <SidebarMenu className="gap-2">
          <HelpItem />
          <DarkModeItem />
          <ProfileItem />
        </SidebarMenu>
      </SidebarFooter>
    </Sidebar>
  );
}

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";

export type Theme = "dark" | "light" | "system";

type ThemeProviderProps = {
  children: ReactNode;
  defaultTheme?: Theme;
  storageKey?: string;
};

type ThemeProviderState = {
  theme: Theme;
  resolvedTheme: "dark" | "light";
  setTheme: (theme: Theme) => void;
};

const ThemeProviderContext = createContext<ThemeProviderState | null>(null);

function getSystemTheme(): "dark" | "light" {
  return window.matchMedia("(prefers-color-scheme: dark)").matches
    ? "dark"
    : "light";
}

export function ThemeProvider({
  children,
  defaultTheme = "system",
  storageKey = "tallie-theme",
}: ThemeProviderProps) {
  const [theme, setThemeState] = useState<Theme>(() => {
    if (typeof window === "undefined") return defaultTheme;

    const stored = localStorage.getItem(storageKey);
    if (stored === "light" || stored === "dark" || stored === "system") {
      return stored;
    }

    return defaultTheme;
  });

  const [systemTheme, setSystemTheme] = useState<"dark" | "light">(() => {
    if (typeof window === "undefined") return "light";
    return getSystemTheme();
  });

  const resolvedTheme = theme === "system" ? systemTheme : theme;

  useEffect(() => {
    const root = document.documentElement;
    root.classList.remove("light", "dark");
    root.classList.add(resolvedTheme);
  }, [resolvedTheme]);

  useEffect(() => {
    const media = window.matchMedia("(prefers-color-scheme: dark)");
    const onChange = () => setSystemTheme(getSystemTheme());
    media.addEventListener("change", onChange);
    return () => media.removeEventListener("change", onChange);
  }, []);

  const setTheme = useCallback(
    (nextTheme: Theme) => {
      localStorage.setItem(storageKey, nextTheme);
      setThemeState(nextTheme);
    },
    [storageKey],
  );

  const value = useMemo(
    () => ({ theme, resolvedTheme, setTheme }),
    [theme, resolvedTheme, setTheme],
  );

  return (
    <ThemeProviderContext.Provider value={value}>
      {children}
    </ThemeProviderContext.Provider>
  );
}

export function useTheme() {
  const context = useContext(ThemeProviderContext);

  if (!context) {
    throw new Error("useTheme must be used within a ThemeProvider.");
  }

  return context;
}

