                <img
                  src={currentUser.avatar}
                  alt=""
                  className="size-8.5 rounded-lg border bg-muted object-cover"
                />
                <CaretDownIcon className="hidden transition-transform md:block" />
              </DropdownMenuTrigger>
              <DropdownMenuContent
                align="end"
                className="tallie-dashboard w-56"
